void s281_opt(int iterations,int LEN_1D, float* a,float* b,float* c)
{
    for (int nl = 0; nl < iterations; nl++) {
        // Process symmetric pairs together to break the dependency
        int i = 0;
        int j = LEN_1D - 1;

        // Process pairs from both ends towards the middle
        for (; i < j; i++, j--) {
            // Process element i (reads from original a[j])
            float x_i = a[j] + b[i] * c[i];
            a[i] = x_i - 1.0f;
            b[i] = x_i;

            // Process element j (reads from original a[i] which hasn't been updated yet)
            float x_j = a[i] + b[j] * c[j];
            a[j] = x_j - 1.0f;
            b[j] = x_j;
        }

        // Handle middle element when LEN_1D is odd
        if (i == j) {
            float x = a[i] + b[i] * c[i];
            a[i] = x - 1.0f;
            b[i] = x;
        }
    }
}

#include <stdint.h>

void vectorized_s281(int iterations, int LEN_1D, float* a, float* b, float* c) {
    for (int nl = 0; nl < iterations; nl++) {
        int i = 0;
        int j = LEN_1D - 1;

        // Process 4 pairs at a time
        for (; i + 3 < j - 3; i += 4, j -= 4) {
            // Load b[i..i+3] and c[i..i+3]
            float b_i0 = b[i];
            float b_i1 = b[i+1];
            float b_i2 = b[i+2];
            float b_i3 = b[i+3];

            float c_i0 = c[i];
            float c_i1 = c[i+1];
            float c_i2 = c[i+2];
            float c_i3 = c[i+3];

            // Load b[j-3..j] and c[j-3..j]
            float b_j3 = b[j-3];
            float b_j2 = b[j-2];
            float b_j1 = b[j-1];
            float b_j0 = b[j];

            float c_j3 = c[j-3];
            float c_j2 = c[j-2];
            float c_j1 = c[j-1];
            float c_j0 = c[j];

            // Load a[j..j-3] for i elements (reverse order)
            float a_j0 = a[j];
            float a_j1 = a[j-1];
            float a_j2 = a[j-2];
            float a_j3 = a[j-3];

            // Compute x_i = a[j] + b[i] * c[i]
            float x_i0 = a_j0 + b_i0 * c_i0;
            float x_i1 = a_j1 + b_i1 * c_i1;
            float x_i2 = a_j2 + b_i2 * c_i2;
            float x_i3 = a_j3 + b_i3 * c_i3;

            // Store a[i] = x_i - 1.0f and b[i] = x_i
            float a_i0_new = x_i0 - 1.0f;
            float a_i1_new = x_i1 - 1.0f;
            float a_i2_new = x_i2 - 1.0f;
            float a_i3_new = x_i3 - 1.0f;

            a[i] = a_i0_new;
            a[i+1] = a_i1_new;
            a[i+2] = a_i2_new;
            a[i+3] = a_i3_new;

            b[i] = x_i0;
            b[i+1] = x_i1;
            b[i+2] = x_i2;
            b[i+3] = x_i3;

            // Compute x_j = a[i]_new + b[j] * c[j] using updated a[i] values
            // Note: x_j3 corresponds to j-3, whose opposite is i+3
            float x_j3 = a_i3_new + b_j3 * c_j3;  // j-3
            float x_j2 = a_i2_new + b_j2 * c_j2;  // j-2
            float x_j1 = a_i1_new + b_j1 * c_j1;  // j-1
            float x_j0 = a_i0_new + b_j0 * c_j0;  // j

            // Store a[j] = x_j - 1.0f and b[j] = x_j
            a[j-3] = x_j3 - 1.0f;
            a[j-2] = x_j2 - 1.0f;
            a[j-1] = x_j1 - 1.0f;
            a[j] = x_j0 - 1.0f;

            b[j-3] = x_j3;
            b[j-2] = x_j2;
            b[j-1] = x_j1;
            b[j] = x_j0;
        }

        // Process remaining pairs
        for (; i < j; i++, j--) {
            float x_i = a[j] + b[i] * c[i];
            a[i] = x_i - 1.0f;
            b[i] = x_i;

            float x_j = a[i] + b[j] * c[j];
            a[j] = x_j - 1.0f;
            b[j] = x_j;
        }

        // Handle middle element when LEN_1D is odd
        if (i == j) {
            float x = a[i] + b[i] * c[i];
            a[i] = x - 1.0f;
            b[i] = x;
        }
    }
}
